package probe;import java.util.Currency;public class CurrencyCodesProbe {public static void main(String[] args){int accepted=0,rejected=0;for(char a='A';a<='Z';a++)for(char b='A';b<='Z';b++)for(char c='A';c<='Z';c++){String code=""+a+b+c;try{Currency value=Currency.getInstance(code);System.out.println(value.getCurrencyCode());accepted++;}catch(IllegalArgumentException expected){rejected++;}}System.out.println("counts:"+accepted+":"+rejected);}}